"""Generates and strictly validates app/src/main/assets/academy-grammar-v61.json.

Every German sentence, answer key, distractor, and grammatical explanation is
authored explicitly for LEXORA V6.1. Existing academy-grammar.tsv (38 topics,
152 items) remains untouched for backward compatibility.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ASSETS = ROOT / "app/src/main/assets"
OUT = ASSETS / "academy-grammar-v61.json"

ALLOWED_TYPES = {
    "Multiple choice",
    "Fill in the blank",
    "Sentence construction",
    "Word order",
    "Verb conjugation",
    "Article selection",
    "Case drill",
    "Sentence correction",
    "Grammar transformation",
    "Grammar in reading context",
}

def q(qtype, prompt, key, choices, why):
    assert qtype in ALLOWED_TYPES, f"Unknown type {qtype}"
    assert prompt.strip() and key.strip() and why.strip(), f"Blank field in {prompt}"
    if choices:
        assert key not in choices, f"Key duplicated in distractors: {prompt}"
        assert len(choices) == len(set(choices)), f"Duplicate distractors: {prompt}"
    return {"type": qtype, "prompt": prompt, "key": key, "choices": choices, "why": why}

def guide(
    tid, category, why_works, pos_ex, neg_ex, mistakes, context, exceptions, comparison, vocab_topics, extra,
    is_new=False, level=None, title=None, prerequisite="", summary=""
):
    obj = {
        "id": tid,
        "isNew": is_new,
        "category": category,
        "whyItWorks": why_works,
        "positiveExamples": pos_ex,
        "negativeExamples": neg_ex,
        "commonMistakes": mistakes,
        "context": context,
        "exceptions": exceptions,
        "comparison": comparison,
        "relatedVocabTopics": vocab_topics,
        "extraExercises": extra,
    }
    if is_new:
        obj["level"] = level
        obj["title"] = title
        obj["prerequisite"] = prerequisite
        obj["explanation"] = summary
    return obj

