# Fix the inline choices expression in subjective_modals cleanly
TOPICS[-1]["extraExercises"][1]["choices"] = ["Physical ability", "Personal boast", "Guaranteed past fact"]
TOPICS[-1]["extraExercises"][1]["key"] = "A reported claim or intention"

def validate():
    tsv_lines = [l.split("|") for l in (ASSETS / "academy-grammar.tsv").read_text(encoding="utf-8").splitlines() if l and not l.startswith("#")]
    tsv_ids = {row[0] for row in tsv_lines}
    seen_ids = set()
    new_topics = 0
    total_extra = 0
    types_seen = set()
    for t in TOPICS:
        tid = t["id"]
        assert tid not in seen_ids, f"Duplicate topic id {tid}"
        seen_ids.add(tid)
        if t["isNew"]:
            assert tid not in tsv_ids, f"New topic collides with TSV: {tid}"
            assert t["level"] in {"A1", "A2", "B1", "B2"}
            assert t["title"].strip() and t["explanation"].strip()
            new_topics += 1
        else:
            assert tid in tsv_ids, f"Existing guide id missing from TSV: {tid}"
        assert t["whyItWorks"].strip()
        assert len(t["positiveExamples"]) >= 1
        assert len(t["negativeExamples"]) >= 1
        assert t["commonMistakes"].strip() and t["context"].strip()
        assert len(t["extraExercises"]) >= 4, f"Too few exercises for {tid}"
        prompts = set()
        for ex in t["extraExercises"]:
            assert ex["prompt"] not in prompts, f"Duplicate prompt in {tid}: {ex['prompt']}"
            prompts.add(ex["prompt"])
            assert ex["type"] in ALLOWED_TYPES
            types_seen.add(ex["type"])
            if ex["choices"]:
                assert ex["key"] not in ex["choices"], f"Key in choices for {tid}: {ex['prompt']}"
            total_extra += 1
    assert tsv_ids.issubset(seen_ids), f"Missing guides for TSV topics: {tsv_ids - seen_ids}"
    assert types_seen == ALLOWED_TYPES, f"Missing exercise types: {ALLOWED_TYPES - types_seen}"
    return new_topics, total_extra, len(seen_ids)

if __name__ == "__main__":
    new_topics, total_extra, total_topics = validate()
    OUT.write_text(json.dumps({"version": 1, "topics": TOPICS}, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"OK: wrote {OUT}")
    print(f"Existing TSV topics enriched: {total_topics - new_topics}")
    print(f"New V6.1 topics added: {new_topics} (total topics: {total_topics})")
    print(f"New V6.1 exercises added: {total_extra} (grand total with 152 TSV items: {total_extra + 152})")
